package org.brightstats.stats;

import java.util.*;
import org.apache.commons.math3.linear.*;
import org.apache.commons.math3.distribution.NormalDistribution;

/** Continuous observed-data Gaussian SEM ML; missing values are NaN, not mean replacements. */
public final class FimlSem {
    private FimlSem(){}
    public record Options(int maxIterations,double gradientTolerance,double functionTolerance,double confidence){public Options{Inference.confidence(confidence);if(maxIterations<1||maxIterations>20000||!(gradientTolerance>0)||!Double.isFinite(gradientTolerance)||!(functionTolerance>0)||!Double.isFinite(functionTolerance))throw new IllegalArgumentException("Invalid FIML optimization settings.");}public static Options defaults(){return new Options(1500,1e-8,1e-12,.95);}}
    public record PatternCount(int[] columns,int rows){public PatternCount{columns=columns.clone();}@Override public int[] columns(){return columns.clone();}}
    public record Term(String parameter,double estimate,double standardError,double sandwichStandardError,double z,double pValue,double lower,double upper){}
    public record Fit(SemModel.Model model,Options options,int suppliedRows,int observations,int emptyRows,int observedPatterns,List<PatternCount> missingPatterns,int iterations,boolean converged,boolean locallyIdentified,boolean boundary,double logLikelihood,double aic,double bic,double[] estimates,double[][] parameterCovariance,double[][] sandwichCovariance,List<Term> terms,double[][] impliedCovariance,double[] impliedMeans,List<String> warnings){
        public Fit{missingPatterns=List.copyOf(missingPatterns);estimates=estimates.clone();parameterCovariance=Matrices.copy(parameterCovariance);sandwichCovariance=Matrices.copy(sandwichCovariance);terms=List.copyOf(terms);impliedCovariance=Matrices.copy(impliedCovariance);impliedMeans=impliedMeans.clone();warnings=List.copyOf(warnings);}
        @Override public double[] estimates(){return estimates.clone();}@Override public double[][] parameterCovariance(){return Matrices.copy(parameterCovariance);}@Override public double[][] sandwichCovariance(){return Matrices.copy(sandwichCovariance);}@Override public double[][] impliedCovariance(){return Matrices.copy(impliedCovariance);}@Override public double[] impliedMeans(){return impliedMeans.clone();}
    }
    public static Fit fit(double[][] data,SemModel.Model model,Options options){Objects.requireNonNull(options);var likelihood=new SemObservedLikelihood(data,model);double[] low=likelihood.lower(),high=likelihood.upper();var optimum=Bfgs.minimize(likelihood::evaluate,likelihood.initial(),low,high,options.maxIterations(),options.gradientTolerance(),options.functionTolerance());double[] theta=optimum.point();int q=theta.length;boolean boundary=false;for(int j=0;j<q;j++)if(Double.isFinite(low[j])&&theta[j]-low[j]<1e-7||Double.isFinite(high[j])&&high[j]-theta[j]<1e-7)boundary=true;double[][] covariance=new double[q][q],robust=new double[q][q];for(var row:covariance)Arrays.fill(row,Double.NaN);for(var row:robust)Arrays.fill(row,Double.NaN);boolean identified=q==0;List<String> warnings=new ArrayList<>();
        if(q>0){double[][] hessian=new double[q][q];for(int j=0;j<q;j++){double step=1e-4*(1+Math.abs(theta[j]));double[] plus=theta.clone(),minus=theta.clone();plus[j]+=step;minus[j]-=step;var a=likelihood.evaluate(plus);var b=likelihood.evaluate(minus);double[] ga=a.gradient(),gb=b.gradient();for(int i=0;i<q;i++)hessian[i][j]=Double.isFinite(a.value())&&Double.isFinite(b.value())?(ga[i]-gb[i])/(2*step):Double.NaN;}for(int i=0;i<q;i++)for(int j=0;j<i;j++)hessian[i][j]=hessian[j][i]=.5*(hessian[i][j]+hessian[j][i]);
            if(Arrays.stream(hessian).flatMapToDouble(Arrays::stream).allMatch(Double::isFinite))try{RealMatrix h=new Array2DRowRealMatrix(hessian);double[] scale=new double[q];for(int j=0;j<q;j++)scale[j]=Math.sqrt(Math.max(0,hessian[j][j]));double[][] normalized=new double[q][q];for(int i=0;i<q;i++)for(int j=0;j<q;j++)normalized[i][j]=hessian[i][j]/(scale[i]*scale[j]);identified=Arrays.stream(normalized).flatMapToDouble(Arrays::stream).allMatch(Double::isFinite)&&Matrices.minEigenvalue(normalized)>1e-9;if(identified&&optimum.converged()&&!boundary){RealMatrix bread=new CholeskyDecomposition(h,1e-8,1e-12).getSolver().getInverse();double[][] scores=likelihood.caseScores(theta),meat=new double[q][q];for(var row:scores)for(int i=0;i<q;i++)for(int j=0;j<q;j++)meat[i][j]+=row[i]*row[j]/likelihood.observations;RealMatrix sandwich=bread.multiply(new Array2DRowRealMatrix(meat)).multiply(bread);for(int i=0;i<q;i++)for(int j=0;j<q;j++){double multiplier=model.parameters().get(i).scale()*model.parameters().get(j).scale()/likelihood.observations;covariance[i][j]=bread.getEntry(i,j)*multiplier;robust[i][j]=sandwich.getEntry(i,j)*multiplier;}}}catch(NonPositiveDefiniteMatrixException|NonSymmetricMatrixException|SingularMatrixException invalid){identified=false;}
        }
        if(!identified)warnings.add("Observed information is singular, indefinite or numerically weak; Wald inference is unavailable.");if(!optimum.converged())warnings.add("Optimizer convergence was not established; results are provisional and Wald inference is unavailable.");if(boundary)warnings.add("A parameter is on a configured bound; ordinary Wald inference is unavailable.");if(likelihood.emptyRows>0)warnings.add(likelihood.emptyRows+" fully unobserved rows contributed no likelihood information and were excluded from the effective observation count.");warnings.add("Continuous multivariate-normal observed-data likelihood assumes ignorable MCAR/MAR missingness and a correctly specified mean/covariance model. This is not MNAR correction or an ordinal estimator.");warnings.add("Every observed pattern uses its own marginal covariance/mean. No mean replacement, artificial case scores or complete-data covariance-model fit indices are supplied. Sandwich covariance does not repair a misspecified mean model or missingness assumption.");
        double[] estimates=new double[q];List<Term> terms=new ArrayList<>();double critical=new NormalDistribution().inverseCumulativeProbability((1+options.confidence())/2);for(int j=0;j<q;j++){var parameter=model.parameters().get(j);double value=estimates[j]=theta[j]*parameter.scale(),se=Math.sqrt(covariance[j][j]),sandwich=Math.sqrt(robust[j][j]);boolean variance=parameter.locations().stream().anyMatch(l->l.kind()==SemModel.Kind.COVARIANCE);double z=variance?Double.NaN:Inference.ratio(value,se);terms.add(new Term(parameter.name(),value,se,sandwich,z,Inference.normalTwoSided(z),value-critical*se,value+critical*se));}var state=likelihood.state(theta);if(state==null)throw new IllegalArgumentException("FIML final state is inadmissible.");double ll=-optimum.evaluation().value()*likelihood.observations;return new Fit(model,options,data.length,likelihood.observations,likelihood.emptyRows,likelihood.patterns.size(),likelihood.patterns.stream().map(p->new PatternCount(p.columns(),p.rows())).toList(),optimum.iterations(),optimum.converged(),identified,boundary,ll,-2*ll+2*q,-2*ll+Math.log(likelihood.observations)*q,estimates,covariance,robust,terms,state.covariance().getData(),state.mean().toArray(),warnings);
    }
}
